      size="icon"
      className={cn("size-7 shrink-0 rounded-full text-muted-foreground hover:text-foreground", className)}
    >
      <ExternalLinkIcon className="h-3.5 w-3.5" />
      <span className="sr-only">{t("attachment-library.actions.open")}</span>
    </Button>
